    for p in CHAPTER.glob('*.html'):
        s=p.read_text()
        s=s.replace('Elle révise le stade à la hausse dans environ 20 % des cas.', 'Lugano rapporte un changement de stade chez 10 à 30 % des patients étudiés, plus souvent vers un stade supérieur ; ce résultat n’est pas une fréquence propre au seul lymphome médiastinal.')
        s=s.replace('L’infiltration de la plèvre ou du péricarde est présente dans 70 à 80 % des cas.', 'La revue de Nappi regroupe une infiltration possible du poumon, de la paroi, de la plèvre et du péricarde dans sa description de 70 à 80 % ; ce chiffre ne mesure pas isolément l’infiltration pleurale ou péricardique.')
        s=s.replace('Aucune source lue ne documente l’effet d’une corticothérapie préalable sur la lisibilité de l’histologie, ni le risque anesthésique d’une masse médiastinale : avis spécialisé avant tout geste.', 'Le risque anesthésique dépend de la compression, de la position et de la réserve cardiorespiratoire. Préparer le geste avec anesthésie et hématologie ; préférer une voie sous anesthésie locale lorsque faisable. Les données sur les corticoïdes avant biopsie diffèrent entre enfants avec masse médiastinale et adultes avec DLBCL : voir la comparaison documentée dans les urgences.')
        s=s.replace('Lacunes : corticothérapie avant biopsie et risque anesthésique non documentés dans les sources lues.', 'Avant biopsie : évaluer le risque anesthésique et discuter les corticoïdes selon le compromis entre urgence et diagnostic ; les populations pédiatriques et adultes ne sont pas interchangeables.')
        s=s.replace('Grossesse, fertilité, pédiatrie : données limitées (rapport de cas, essais en cours) ; ne pas transformer un cas en recommandation.', 'Grossesse et fertilité : recommandations Onkopedia distinctes du cas illustratif. Pédiatrie : protocole spécialisé et indications de chaque produit ; un essai en cours ne vaut pas recommandation.')
        s=s.replace('entre J1 et J12 dans ZUMA-1 et ZUMA-7)', 'avec débuts entre J1 et J12 dans ZUMA-1 et ZUMA-7, sans que J12 marque une fin de surveillance)')
        s=s.replace('du jour 1 au jour 12 dans ZUMA-1 et ZUMA-7 ;', 'avec débuts entre J1 et J12 dans ZUMA-1 et ZUMA-7, sans exclure des événements plus tardifs ;')
        s=s.replace('œdème cérébral signalé après Yescarta à un taux de 1,6 %', 'œdème cérébral après autorisation de Yescarta : taux de signalement de 1,6 %')
        s=s.replace('91 % pour 0–1 point, 81 % pour 2, 65 % pour 3, 59 % pour 4–5.', 'Dans les données de DLBCL d’Onkopedia : 91 % pour 0–1 point, 81 % pour 2, 65 % pour 3, 59 % pour 4–5 ; ces valeurs ne sont pas une prédiction individuelle validée du lymphome médiastinal.')
